        afterchangeform.setValues(afterchange);

        var rgdt = (aprHistData) ? record.aplDtm : record.fstRgDtti;		// 휴일근무신청(aplDtm) , 결재함(fstRgDtti)
        refs.rgdt.setHtml(rgdt.substr(0,10));
        refs.headTitle.setHtml( "휴일근무"+ (afterchange.aplDvcd == '01' ? '신청' : '취소신청' ));
